# Format of /opt/apollo/env/test-env.sh on the DigitalOcean test-environment droplet. The real file is GENERATED by
# `provision.sh envfile` (it computes every SHA-256 below from the files on the host); this example only documents the shape.
# Source it:   . /opt/apollo/env/test-env.sh
#
# NO SECRET belongs here. The credentials below are the throw-away test ones the CI itself uses (apollo/apollo-ci for PostgreSQL,
# apollo-ci-storage for MinIO). Provider keys (Groq etc.) are passed per process at test time, e.g.
#   GROQ_API_KEY=... npm run test:e2e:...        (never exported into a file, never committed, never part of a snapshot)
#
# CI-faithful `npm test` runs WITHOUT the APOLLO_V2_PIXEL_ORACLE_* / APOLLO_V2_FACE_V9_* variables (the CI does not set them):
#   for v in $(compgen -e | grep -E '^APOLLO_V2_(PIXEL_ORACLE|FACE_V9)_'); do unset "$v"; done

export CI=true
export APOLLO_API_ENVIRONMENT=production
export V2_DATABASE_URL='postgresql://apollo:apollo-ci@127.0.0.1:5432/apollo_v2?schema=public'
export PLAYWRIGHT_BROWSERS_PATH='/opt/apollo/ms-playwright'
export PLAYWRIGHT_CHROME_EXECUTABLE=/usr/local/bin/playwright-chromium
# CI: ffprobe is the distribution one; ffmpeg itself stays the pinned ffmpeg-static (approved-final tests compare its binary).
export FFPROBE_PATH=/usr/bin/ffprobe
export PYTHON='/opt/apollo/venv-ops/bin/python'

# Variables the CI runner provides to the pidfd addon build/consumer (the build writes the APOLLO_PERCEPTION_PIDFD_* lines into GITHUB_ENV).
export RUNNER_TEMP='/opt/apollo/runner-temp'
export GITHUB_SHA='<git sha of /opt/apollo/apollo-video>'
export APOLLO_PERCEPTION_PIDFD_ROOT=/opt/apollo/runner-temp/apollo-ci-pidfd.<random>
export APOLLO_PERCEPTION_PIDFD_ADDON=/opt/apollo/runner-temp/apollo-ci-pidfd.<random>/perception-pidfd.node
export APOLLO_PERCEPTION_PIDFD_PROVENANCE=/opt/apollo/runner-temp/apollo-ci-pidfd.<random>/provenance.json
export APOLLO_PERCEPTION_PIDFD_SHA256=<sha256 of the built addon>

# MinIO (S3-compatible), the CI compose job credentials
export APOLLO_V2_S3_ENDPOINT=http://127.0.0.1:59000
export APOLLO_V2_S3_REGION=us-east-1
export APOLLO_V2_S3_FORCE_PATH_STYLE=true
export APOLLO_V2_S3_ALLOW_INSECURE_HTTP=true
export APOLLO_V2_S3_ACCESS_KEY_ID=apollo-ci-storage
export APOLLO_V2_S3_SECRET_ACCESS_KEY=apollo-ci-storage-password

# W67 MP4 pixel critic: all seven or none (docs/quality/w67-final-pixel-oracle-v1.md)
export APOLLO_V2_PIXEL_ORACLE_PYTHON='/opt/apollo/venv-oracle/bin/python'
export APOLLO_V2_PIXEL_ORACLE_PYTHON_SHA256=<sha256 of the resolved python3.12 binary>
export APOLLO_V2_PIXEL_ORACLE_MODULES='/opt/apollo/oracle-pydeps'
export APOLLO_V2_PIXEL_ORACLE_V9_MODEL_DIR='/opt/apollo/models'
export APOLLO_V2_PIXEL_ORACLE_RETAIL_MODEL_DIR='/opt/apollo/models'
export APOLLO_V2_PIXEL_ORACLE_BRIDGE='/opt/apollo/apollo-video/src/v2/infrastructure/perception/openvino_pixel_oracle_bridge.py'
export APOLLO_V2_PIXEL_ORACLE_BRIDGE_SHA256=<sha256 of the bridge at the checked-out commit>

# W62 V9 face window worker. createFaceWindowWorker still REFUSES linux: the producer registry has no parity receipt for it.
export APOLLO_V2_FACE_V9_PYTHON_BIN='/opt/apollo/venv-oracle/bin/python'
export APOLLO_V2_FACE_V9_PYTHON_SHA256=<same as the oracle python>
export APOLLO_V2_FACE_V9_PYTHON_MODULE_DIR='/opt/apollo/oracle-pydeps'
export APOLLO_V2_FACE_V9_RUNTIME_MANIFEST='/opt/apollo/env/face-runtime-manifest.json'
export APOLLO_V2_FACE_V9_RUNTIME_MANIFEST_SHA256=<manifestSha256 printed by scripts/ops/build-face-runtime-manifest.mjs>
export APOLLO_V2_FACE_V9_MODEL_XML='/opt/apollo/models/face-detection-0204.xml'
export APOLLO_V2_FACE_V9_MODEL_BIN='/opt/apollo/models/face-detection-0204.bin'
export APOLLO_V2_FACE_V9_BRIDGE_SCRIPT='/opt/apollo/apollo-video/src/v2/infrastructure/perception/openvino_face0204_bridge.py'
export APOLLO_V2_FACE_V9_BRIDGE_SHA256=<sha256 of the bridge at the checked-out commit>
export APOLLO_V2_FACE_V9_FFMPEG_BIN=/usr/bin/ffmpeg
export APOLLO_V2_FACE_V9_FFMPEG_SHA256=<sha256 of the resolved ffmpeg>
export APOLLO_V2_FACE_V9_FFPROBE_BIN=/usr/bin/ffprobe
export APOLLO_V2_FACE_V9_FFPROBE_SHA256=<sha256 of the resolved ffprobe>
export APOLLO_V2_FACE_V9_MODEL_LICENSE='/opt/apollo/models/LICENSE'
export APOLLO_V2_FACE_V9_MODEL_LICENSE_SHA256=c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4
